CREATE TABLE IF NOT EXISTS agent_profiles (user_id TEXT PRIMARY KEY, email TEXT NOT NULL, display_name TEXT NOT NULL DEFAULT '', role TEXT NOT NULL DEFAULT 'agent' CHECK (role IN ('manager','agent')), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS daily_kpis (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), agent_user_id TEXT NOT NULL REFERENCES agent_profiles(user_id), work_date DATE NOT NULL, calls_assigned INTEGER NOT NULL DEFAULT 0, outbound_attempts INTEGER NOT NULL DEFAULT 0, inbound_calls INTEGER NOT NULL DEFAULT 0, connected_calls INTEGER NOT NULL DEFAULT 0, qualified_leads INTEGER NOT NULL DEFAULT 0, consultations_booked INTEGER NOT NULL DEFAULT 0, whatsapp_shared INTEGER NOT NULL DEFAULT 0, callbacks_scheduled INTEGER NOT NULL DEFAULT 0, followups_completed INTEGER NOT NULL DEFAULT 0, crm_updated INTEGER NOT NULL DEFAULT 0, talk_time_minutes NUMERIC(10,2) NOT NULL DEFAULT 0, notes TEXT NOT NULL DEFAULT '', updated_by TEXT NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(agent_user_id, work_date));
CREATE TABLE IF NOT EXISTS quiz_attempts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id TEXT NOT NULL, quiz_date DATE NOT NULL DEFAULT CURRENT_DATE, score INTEGER NOT NULL, total INTEGER NOT NULL, answers JSONB NOT NULL DEFAULT '[]'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());